    protected function doInsert(PropelPDO $con)
    {
        $this->modifiedColumns[] = DependenciaPeer::DEPENDENCIA_ID;
        $criteria = $this->buildCriteria();
        if ($criteria->keyContainsValue(DependenciaPeer::DEPENDENCIA_ID) ) {
            throw new PropelException('Cannot insert a value for auto-increment primary key (' . DependenciaPeer::DEPENDENCIA_ID . ')');
        }
        // remove pkey col since this table uses auto-increment and passing a null value for it is not valid
        $criteria->remove(DependenciaPeer::DEPENDENCIA_ID);
        $pk = BasePeer::doInsert($criteria, $con);
        $this->setDependenciaId($pk);  //[IMV] update autoincrement primary key
        $this->setNew(false);
    }

