    public function countReceptors(Criteria $criteria = null, $distinct = false, PropelPDO $con = null)
    {
        $partial = $this->collReceptorsPartial && !$this->isNew();
        if (null === $this->collReceptors || null !== $criteria || $partial) {
            if ($this->isNew() && null === $this->collReceptors) {
                return 0;
            }

            if ($partial && !$criteria) {
                return count($this->getReceptors());
            }
            $query = ReceptorQuery::create(null, $criteria);
            if ($distinct) {
                $query->distinct();
            }

            return $query
                ->filterByDependencia($this)
                ->count($con);
        }

        return count($this->collReceptors);
    }

